window.initSlideImg=function(){document.querySelectorAll("[data-img-slide]").forEach(i=>{i.querySelectorAll("[data-img-slide-src]").forEach(e=>{e.addEventListener("click",function(){i.querySelectorAll("[data-img-slide-src]").forEach(d=>{d.classList.remove("is-active")}),this.classList.add("is-active");const t=`${this.dataset.imgSlideSrc}`;i.querySelector("[data-img-slide-img]").src=t})})})},window.addEventListener("load",window.initSlideImg);
